// Similar: conditional rendering in a function
function withPermission(WrappedComponent) {
  return function(props) {
    const hasPermission = true;
    if (hasPermission) {
      return <WrappedComponent {...props} />;
    } else {
      return <p>Access denied.</p>;
    }
  };
}

